CREATE TRIGGER IF NOT EXISTS team_ledger_insert AFTER INSERT ON agent_ledger FOR EACH ROW INSERT INTO team_ledger_journal(ledger_id,event_type,new_row) VALUES(NEW.id,'insert',JSON_OBJECT('agent',NEW.agent_admin_id,'booking',NEW.booking_id,'type',NEW.entry_type,'account',NEW.account,'amount',NEW.amount,'ref',NEW.ref,'note',NEW.note));
CREATE TRIGGER IF NOT EXISTS team_ledger_update AFTER UPDATE ON agent_ledger FOR EACH ROW INSERT INTO team_ledger_journal(ledger_id,event_type,old_row,new_row) VALUES(OLD.id,'update',JSON_OBJECT('agent',OLD.agent_admin_id,'booking',OLD.booking_id,'type',OLD.entry_type,'account',OLD.account,'amount',OLD.amount,'ref',OLD.ref,'note',OLD.note),JSON_OBJECT('agent',NEW.agent_admin_id,'booking',NEW.booking_id,'type',NEW.entry_type,'account',NEW.account,'amount',NEW.amount,'ref',NEW.ref,'note',NEW.note));
CREATE TRIGGER IF NOT EXISTS team_ledger_delete AFTER DELETE ON agent_ledger FOR EACH ROW INSERT INTO team_ledger_journal(ledger_id,event_type,old_row) VALUES(OLD.id,'delete',JSON_OBJECT('agent',OLD.agent_admin_id,'booking',OLD.booking_id,'type',OLD.entry_type,'account',OLD.account,'amount',OLD.amount,'ref',OLD.ref,'note',OLD.note));
